# Step 4: Static directed reachability from 798 to 131 ignoring time within window
start, end = 4302, 42701
subset = [e for e in events if start <= e[2] <= end]
from collections import defaultdict, deque
adj = defaultdict(set)
nodes = set()
for u,v,t in subset:
    adj[u].add(v)
    nodes.add(u); nodes.add(v)
# BFS
src=798; tgt=131
q=deque([src]); seen={src}
prev = {}
found=False
while q:
    u = q.popleft()
    if u==tgt:
        found=True; break
    for v in adj.get(u,[]):
        if v not in seen:
            seen.add(v); prev[v]=u; q.append(v)
print('Static directed path exists:', found)
if found:
    path=[tgt]
    cur=tgt
    while cur!=src:
        cur=prev[cur]; path.append(cur)
    path.reverse();
    print('Path:', path)
else:
    # print reachable nodes from src
    print('Reachable count from src:', len(seen))
    print('Some reachable nodes (first 50):')
    print(sorted(list(seen))[:50])
# Print out-degree of 798 and in-degree of 131 in window
out_deg_798 = len(adj.get(798,[]))
in_deg_131 = sum(1 for u in adj if 131 in adj[u])
print('out_deg_798:', out_deg_798, 'in_deg_131:', in_deg_131)
# Print direct edges list involving 798 or 131
print('Edges involving 798 or 131:')
for u in adj:
